constexpr unsigned field_count=11,max_items=8;
const char* captions[]={"Produto ID","Quantidade","Desc. item R$","Desc. item %","Cliente ID (0=sem)","Desc. venda R$","Desc. venda %","Pagamento 1 R$","Pagamento 2 R$","Pesquisar produto","Motivo cancelamento"};
const char* methods[]={"cash","pix","debit","credit","transfer","other"};
enum class Mode {Cart,Search,CustomerSearch,Review,Pending,Receipt,History,Cancel,Blocked};
enum class Action {Init,Add,Remove,Search,CustomerSearch,Select,Refresh,Quote,Finish,Retry,Resolve,History,Detail,Cancel,New};
struct Item {int id,version;char name[481];int64_t price,quantity,amount,percent;};
struct Row {int id;char label[650];};
struct State {unsigned serial,count,next;int user,sale;bool busy,pending,canceled;Mode mode;Item items[max_items];unsigned size;Row rows[8];char message[350],summary[16385];};
struct Command {Action action;unsigned generation,after;int id;unsigned payment[2];char fields[field_count][961];};
struct Workspace {State state,draw,working;Command command;char permissions[2048],response[16385],payload[4097],pending[4097];};
Workspace* w;QueueHandle_t queue;SemaphoreHandle_t mutex;std::atomic<unsigned> generation{0};std::atomic<bool> visible{false};
lv_obj_t *root,*title,*notice,*preview,*list,*receipt_panel,*summary,*fields[field_count],*labels[field_count],*rows[8],*buttons[8],*payments[2],*keyboard;void(*home_callback)();unsigned drawn=0;
const char* value(cJSON* o,const char* key){auto* v=cJSON_GetObjectItemCaseSensitive(o,key);return cJSON_IsString(v)?v->valuestring:"";}
int integer(cJSON* o,const char* key){auto* v=cJSON_GetObjectItemCaseSensitive(o,key);return cJSON_IsNumber(v)?v->valueint:0;}
bool permitted(const char* p,const char* code){return has_module_permission(p,code);}
void publish(const Command& cmd,const char* message){xSemaphoreTake(mutex,portMAX_DELAY);if(cmd.generation==generation){w->working.busy=false;snprintf(w->working.message,sizeof(w->working.message),"%s",message);w->working.serial=w->state.serial+1;w->state=w->working;}xSemaphoreGive(mutex);}
void enqueue(Action action,int id=0,unsigned after=0){if(!visible)return;
    // Queue receives a copy; GUI and worker use separate storage for commands.
    auto* local=static_cast<Command*>(heap_caps_calloc(1,sizeof(Command),MALLOC_CAP_SPIRAM|MALLOC_CAP_8BIT));if(!local)return;
    xSemaphoreTake(mutex,portMAX_DELAY);if(w->state.busy){xSemaphoreGive(mutex);free(local);return;}
    local->action=action;local->id=id;local->after=after;local->generation=generation;
    for(unsigned i=0;i<field_count;++i)snprintf(local->fields[i],sizeof(local->fields[i]),"%s",lv_textarea_get_text(fields[i]));
    for(unsigned i=0;i<2;++i)local->payment[i]=lv_dropdown_get_selected(payments[i]);
    if(xQueueSend(queue,local,0)==pdTRUE){w->state.busy=true;++w->state.serial;snprintf(w->state.message,sizeof(w->state.message),"Aguarde...");}
    xSemaphoreGive(mutex);free(local);
}
void keyboard_event(lv_event_t* e){lv_keyboard_set_textarea(keyboard,lv_event_get_target_obj(e));lv_obj_remove_flag(keyboard,LV_OBJ_FLAG_HIDDEN);}
void row_event(lv_event_t* e){if(w->draw.busy)return;int id=static_cast<int>(reinterpret_cast<intptr_t>(lv_event_get_user_data(e)));if(w->draw.mode==Mode::CustomerSearch){char text[24];snprintf(text,sizeof(text),"%d",id);lv_textarea_set_text(fields[4],text);xSemaphoreTake(mutex,portMAX_DELAY);w->state.mode=Mode::Cart;++w->state.serial;snprintf(w->state.message,sizeof(w->state.message),"Cliente ID %d selecionado; API validará na finalização.",id);xSemaphoreGive(mutex);}
    else if(w->draw.mode==Mode::Search)enqueue(Action::Select,id);else if(w->draw.mode==Mode::History)enqueue(Action::Detail,id);else{char text[48];snprintf(text,sizeof(text),"%d",id);lv_textarea_set_text(fields[0],text);for(unsigned i=0;i<w->draw.size;++i){const auto& item=w->draw.items[i];if(item.id!=id)continue;money::format(text,sizeof(text),item.quantity,3);lv_textarea_set_text(fields[1],text);money::format(text,sizeof(text),item.amount);lv_textarea_set_text(fields[2],text);money::format(text,sizeof(text),item.percent);lv_textarea_set_text(fields[3],text);break;}}}
void click(lv_event_t* e){unsigned i=reinterpret_cast<uintptr_t>(lv_event_get_user_data(e));if(i==7){sales_hide();home_callback();return;}const auto& s=w->draw;
    if(s.mode==Mode::Cart){if(i==6){for(unsigned f=0;f<9;++f)lv_textarea_set_text(fields[f],f==1?"1":"0");}Action actions[]={Action::Add,Action::Remove,Action::Search,Action::Quote,Action::Refresh,Action::History,Action::New};enqueue(actions[i]);}
    else if(s.mode==Mode::Pending){if(i==0)enqueue(Action::Retry);if(i==1)enqueue(Action::Resolve);}
    else if(s.mode==Mode::Review){if(i==0)enqueue(Action::Finish);if(i==1){xSemaphoreTake(mutex,portMAX_DELAY);w->state.mode=Mode::Cart;++w->state.serial;xSemaphoreGive(mutex);}}
    else if(s.mode==Mode::Search||s.mode==Mode::CustomerSearch||s.mode==Mode::History){if(i==0)enqueue(s.mode==Mode::Search?Action::Search:s.mode==Mode::CustomerSearch?Action::CustomerSearch:Action::History,0,s.next);if(i==1){xSemaphoreTake(mutex,portMAX_DELAY);w->state.mode=Mode::Cart;++w->state.serial;xSemaphoreGive(mutex);}if(i==2)enqueue(s.mode==Mode::CustomerSearch?Action::Search:Action::CustomerSearch);if(i==3)enqueue(s.mode==Mode::CustomerSearch?Action::CustomerSearch:Action::Search);}
    else if(s.mode==Mode::Receipt){if(i==0){for(unsigned f=0;f<9;++f)lv_textarea_set_text(fields[f],f==1?"1":"0");enqueue(Action::New);}if(i==1)enqueue(Action::History);if(i==2){xSemaphoreTake(mutex,portMAX_DELAY);w->state.mode=Mode::Cancel;++w->state.serial;xSemaphoreGive(mutex);}}
    else if(s.mode==Mode::Cancel){if(i==0)enqueue(Action::Cancel,s.sale);if(i==1)enqueue(Action::Detail,s.sale);}
}
void render(lv_timer_t*){if(!visible)return;xSemaphoreTake(mutex,portMAX_DELAY);w->draw=w->state;xSemaphoreGive(mutex);auto& s=w->draw;if(s.serial==drawn)return;drawn=s.serial;
    lv_label_set_text(title,s.mode==Mode::Pending?"PDV | Tentativa pendente":s.mode==Mode::History?"PDV | Histórico":s.mode==Mode::CustomerSearch?"PDV | Clientes":s.mode==Mode::Search?"PDV | Produtos":s.mode==Mode::Review?"PDV | Confirmar venda":s.mode==Mode::Receipt?"Comprovante NÃO FISCAL":s.mode==Mode::Cancel?"PDV | Cancelar venda":"Vendas / PDV");lv_label_set_text(notice,s.message);
    if(s.mode==Mode::Cart){
        int64_t gross=0,discount=0;bool valid=true;
        for(unsigned i=0;i<s.size;++i){int64_t line=0;if(!money::line(s.items[i].price,s.items[i].quantity,line)||gross>99999999999999LL-line){valid=false;break;}gross+=line;int64_t cut=s.items[i].amount?s.items[i].amount:money::percent(line,s.items[i].percent);if(cut>line){valid=false;break;}discount+=cut;}
        int64_t amount=0,percent=0;
        if(!money::parse(lv_textarea_get_text(fields[5]),2,amount)||!money::parse(lv_textarea_get_text(fields[6]),2,percent)||percent>10000||(amount&&percent))valid=false;
        if(valid){int64_t cut=amount?amount:money::percent(gross-discount,percent);if(cut>gross-discount)valid=false;else discount+=cut;}
        char subtotal[48],cut[48],total[48],info[240];money::format(subtotal,sizeof(subtotal),gross);money::format(cut,sizeof(cut),discount);money::format(total,sizeof(total),valid?gross-discount:0);
        snprintf(info,sizeof(info),"Prévia: subtotal R$ %s | desconto R$ %s | total R$ %s | API confirma.",subtotal,cut,valid?total:"inválido");lv_label_set_text(preview,info);lv_obj_remove_flag(preview,LV_OBJ_FLAG_HIDDEN);
    }else lv_obj_add_flag(preview,LV_OBJ_FLAG_HIDDEN);
    bool cart=s.mode==Mode::Cart,listing=cart||s.mode==Mode::Search||s.mode==Mode::CustomerSearch||s.mode==Mode::History;
    for(unsigned i=0;i<field_count;++i){bool show=(cart&&i<10)||((s.mode==Mode::Search||s.mode==Mode::CustomerSearch)&&i==9)||(s.mode==Mode::Cancel&&i==10);for(auto* o:{fields[i],labels[i]}){if(show)lv_obj_remove_flag(o,LV_OBJ_FLAG_HIDDEN);else lv_obj_add_flag(o,LV_OBJ_FLAG_HIDDEN);}if(s.busy)lv_obj_add_state(fields[i],LV_STATE_DISABLED);else lv_obj_remove_state(fields[i],LV_STATE_DISABLED);}
    for(auto* p:payments){if(cart)lv_obj_remove_flag(p,LV_OBJ_FLAG_HIDDEN);else lv_obj_add_flag(p,LV_OBJ_FLAG_HIDDEN);if(s.busy)lv_obj_add_state(p,LV_STATE_DISABLED);else lv_obj_remove_state(p,LV_STATE_DISABLED);}
    static Mode previous=Mode::Blocked;if(s.mode!=previous||s.busy)lv_obj_add_flag(keyboard,LV_OBJ_FLAG_HIDDEN);previous=s.mode;if(listing){lv_obj_remove_flag(list,LV_OBJ_FLAG_HIDDEN);lv_obj_add_flag(receipt_panel,LV_OBJ_FLAG_HIDDEN);}else{lv_obj_add_flag(list,LV_OBJ_FLAG_HIDDEN);lv_obj_remove_flag(receipt_panel,LV_OBJ_FLAG_HIDDEN);lv_label_set_text(summary,s.summary);lv_obj_set_height(receipt_panel,s.mode==Mode::Cancel?310:400);}
    for(unsigned i=0;i<8;++i){lv_obj_remove_event_cb(rows[i],row_event);if(listing&&i<(cart?s.size:s.count)){char line[650];if(cart){char price[40],qty[40];money::format(price,sizeof(price),s.items[i].price);money::format(qty,sizeof(qty),s.items[i].quantity,3);snprintf(line,sizeof(line),"ID %d | %s | %s x R$ %s",s.items[i].id,s.items[i].name,qty,price);}else snprintf(line,sizeof(line),"%s",s.rows[i].label);lv_label_set_text(lv_obj_get_child(rows[i],0),line);lv_obj_remove_flag(rows[i],LV_OBJ_FLAG_HIDDEN);lv_obj_add_event_cb(rows[i],row_event,LV_EVENT_CLICKED,reinterpret_cast<void*>(static_cast<intptr_t>(cart?s.items[i].id:s.rows[i].id)));}else lv_obj_add_flag(rows[i],LV_OBJ_FLAG_HIDDEN);}
    const char* names[8]={"","","","","","","","Menu"};
    if(cart){names[0]="Adicionar / editar";names[1]="Remover";names[2]="Pesquisar";names[3]="Calcular venda";names[4]="Atualizar preços";names[5]="Histórico";names[6]="Limpar carrinho";}
    if(s.mode==Mode::Review){names[0]="Finalizar venda";names[1]="Voltar";}
    if(s.mode==Mode::Pending){names[0]="Reenviar";names[1]="Resolver tentativa";}
    if(s.mode==Mode::History||s.mode==Mode::Search||s.mode==Mode::CustomerSearch){names[0]="Próxima";names[1]="Voltar";if(s.mode!=Mode::History){names[2]=s.mode==Mode::CustomerSearch?"Buscar produto":"Buscar cliente";names[3]="Pesquisar";}}
    if(s.mode==Mode::Receipt){names[0]=s.pending?"Resolver tentativa":"Nova venda";names[1]="Histórico";if(!s.canceled&&permitted(w->permissions,"sales.cancel"))names[2]="Cancelar venda";}
    if(s.mode==Mode::Cancel){names[0]="Confirmar cancel.";names[1]="Voltar";}
    for(unsigned i=0;i<8;++i){lv_label_set_text(lv_obj_get_child(buttons[i],0),names[i]);lv_obj_center(lv_obj_get_child(buttons[i],0));if(*names[i])lv_obj_remove_flag(buttons[i],LV_OBJ_FLAG_HIDDEN);else lv_obj_add_flag(buttons[i],LV_OBJ_FLAG_HIDDEN);if((s.busy&&i!=7)||(i==0&&(s.mode==Mode::Search||s.mode==Mode::CustomerSearch||s.mode==Mode::History)&&!s.next))lv_obj_add_state(buttons[i],LV_STATE_DISABLED);else lv_obj_remove_state(buttons[i],LV_STATE_DISABLED);}
}
cJSON* cart_json(const Command& cmd,bool payment){auto* body=cJSON_CreateObject();auto* items=cJSON_AddArrayToObject(body,"items");char num[48];for(unsigned i=0;i<w->working.size;++i){auto& item=w->working.items[i];auto* j=cJSON_CreateObject();cJSON_AddItemToArray(items,j);cJSON_AddNumberToObject(j,"product_id",item.id);cJSON_AddNumberToObject(j,"product_version",item.version);money::format(num,sizeof(num),item.quantity,3);cJSON_AddStringToObject(j,"quantity",num);money::format(num,sizeof(num),item.price);cJSON_AddStringToObject(j,"expected_unit_price",num);money::format(num,sizeof(num),item.amount);cJSON_AddStringToObject(j,"discount_amount",num);money::format(num,sizeof(num),item.percent);cJSON_AddStringToObject(j,"discount_percent",num);}
    int64_t parsed=0;if(!money::parse(cmd.fields[4],0,parsed)||parsed>2147483647){cJSON_Delete(body);return nullptr;}if(parsed)cJSON_AddNumberToObject(body,"customer_id",parsed);
    for(unsigned i=5;i<=6;++i){if(!money::parse(cmd.fields[i],2,parsed)||(i==6&&parsed>10000)){cJSON_Delete(body);return nullptr;}money::format(num,sizeof(num),parsed);cJSON_AddStringToObject(body,i==5?"discount_amount":"discount_percent",num);}
    if(payment){auto* pays=cJSON_AddArrayToObject(body,"payments");for(unsigned i=0;i<2;++i){if(!money::parse(cmd.fields[7+i],2,parsed)){cJSON_Delete(body);return nullptr;}if(parsed){auto* p=cJSON_CreateObject();cJSON_AddItemToArray(pays,p);cJSON_AddStringToObject(p,"method",methods[cmd.payment[i]<6?cmd.payment[i]:0]);money::format(num,sizeof(num),parsed);cJSON_AddStringToObject(p,"amount",num);}}}return body;
}
void receipt(cJSON* data){auto& s=w->working;s.sale=integer(data,"id");s.canceled=!strcmp(value(data,"status"),"canceled");s.mode=Mode::Receipt;snprintf(s.summary,sizeof(s.summary),"Venda %d | %s | %s\nCliente ID %d | Operador ID %d\nSubtotal R$ %s | Desconto R$ %s\nTotal R$ %s | Recebido R$ %s | Troco R$ %s\n\n",s.sale,s.canceled?"CANCELADA":"Concluída",value(data,"created_at"),integer(data,"customer_id"),integer(data,"operator_id"),value(data,"subtotal"),value(data,"discount"),value(data,"total"),value(data,"tendered"),value(data,"change"));auto append=[&](const char* line){size_t n=strlen(s.summary);snprintf(s.summary+n,sizeof(s.summary)-n,"%s",line);};cJSON* item;auto* items=cJSON_GetObjectItemCaseSensitive(data,"items");cJSON_ArrayForEach(item,items){char line[650];snprintf(line,sizeof(line),"%s | %s x R$ %s = R$ %s\n",value(item,"name"),value(item,"quantity"),value(item,"unit_price"),value(item,"subtotal"));append(line);}auto* pays=cJSON_GetObjectItemCaseSensitive(data,"payments");cJSON_ArrayForEach(item,pays){char line[160];snprintf(line,sizeof(line),"%s R$ %s | %s\n",value(item,"method"),value(item,"amount"),value(item,"status"));append(line);}if(s.canceled){append("\nMotivo: ");append(value(data,"cancel_reason"));append("\n");}append("\nPagamentos declarados pelo operador. Documento NÃO FISCAL.\nCancelamento gerencial não confirma estorno externo.");}
bool decode_product(cJSON* data,Item& item){item.id=integer(data,"id");item.version=integer(data,"version");snprintf(item.name,sizeof(item.name),"%s",value(data,"name"));return item.id>0&&item.version>0&&cJSON_IsTrue(cJSON_GetObjectItemCaseSensitive(data,"active"))&&money::parse(value(data,"sale_price"),2,item.price);}
const char* failure(int code,cJSON* data){auto* error=cJSON_GetObjectItemCaseSensitive(data,"error");const char* m=value(error,"message");if(*m)return m;return code<=0?"Sem resposta da API. Confira Wi-Fi, hora e servidor.":"Operação recusada pela API. Atualize os dados e confira os campos.";}
