    if(cmd->action==Action::Quote){auto* body=cart_json(*cmd,false);if(!body)return complete("Confira cliente, descontos e valores com até 2 casas decimais.");raw=cJSON_PrintUnformatted(body);cJSON_Delete(body);snprintf(path,sizeof(path),"/api/v1/sales/quote");method="POST";}
    else if(cmd->action==Action::Finish){if(w->working.mode!=Mode::Review||!w->payload[0])return complete("Calcule e revise a venda antes de finalizar.");uint8_t bytes[16];esp_fill_random(bytes,sizeof(bytes));char key[33];for(unsigned i=0;i<16;++i)snprintf(key+2*i,3,"%02x",bytes[i]);auto* body=cJSON_Parse(w->payload);cJSON_AddStringToObject(body,"idempotency_key",key);raw=cJSON_PrintUnformatted(body);cJSON_Delete(body);if(!raw||strlen(raw)>=sizeof(w->pending)){cJSON_free(raw);return complete("Carrinho excede limite de armazenamento.");}snprintf(w->pending,sizeof(w->pending),"%s",raw);cJSON_free(raw);raw=nullptr;if(journal("save",w->working.user,w->pending,sizeof(w->pending))!=1)return complete("Falha ao registrar tentativa no microSD. Venda não enviada.");w->working.pending=true;w->working.mode=Mode::Pending;snprintf(path,sizeof(path),"/api/v1/sales");method="POST";}
