    const char* body=(cmd->action==Action::Finish||cmd->action==Action::Retry)?w->pending:raw;int code=call(method,path,body);cJSON_free(raw);auto* data=cJSON_Parse(w->response);std::string message;
    if(code<200||code>=300){message=failure(code,data);if(w->working.pending){w->working.mode=Mode::Pending;snprintf(w->working.summary,sizeof(w->working.summary),"Resultado ainda não confirmado. Reenviar repete a MESMA tentativa; Resolver confirma ou encerra a tentativa na API. Não gere uma nova venda para substituir esta pendência.");}}
    else if(cmd->action==Action::Quote){auto* final_body=cart_json(*cmd,true);char* payload=final_body?cJSON_PrintUnformatted(final_body):nullptr;cJSON_Delete(final_body);if(!payload||strlen(payload)>=sizeof(w->payload)){message="Confira os pagamentos e o limite do carrinho.";}else{snprintf(w->payload,sizeof(w->payload),"%s",payload);w->working.mode=Mode::Review;snprintf(w->working.summary,sizeof(w->working.summary),"Subtotal R$ %s\nDescontos R$ %s\nTOTAL R$ %s\n\nPagamento 1: %s R$ %s\nPagamento 2: %s R$ %s\nCliente ID: %s\n\nPagamentos declarados pelo operador.\nConfirme apenas após conferir os valores e receber o pagamento.\nPreço e estoque serão novamente validados na finalização.",value(data,"subtotal"),value(data,"discount"),value(data,"total"),methods[cmd->payment[0]],cmd->fields[7],methods[cmd->payment[1]],cmd->fields[8],cmd->fields[4]);message="Revise. Finalizar grava venda, pagamentos e estoque em uma transação.";}cJSON_free(payload);}
    else if(cmd->action==Action::History){w->working.mode=Mode::History;w->working.count=0;w->working.next=integer(data,"next_id");cJSON* p;auto* items=cJSON_GetObjectItemCaseSensitive(data,"items");cJSON_ArrayForEach(p,items){if(w->working.count>=8)break;auto& row=w->working.rows[w->working.count++];row.id=integer(p,"id");snprintf(row.label,sizeof(row.label),"Venda %d | %s | R$ %s | %s",row.id,value(p,"created_at"),value(p,"total"),value(p,"status"));}message="Toque para consultar os valores originais da venda.";}
